def render_admonition(self: Any, text: str, name: str) ->str:
    html = '<div class="admonition ' + name + '">\n'
    html += text
    html += '</div>\n'
    return html

def parse(self, block: 'BlockParser', m: Match[str], state: 'BlockState'
    ) ->Dict[str, Any]:
    name = self.parse_type(m)
    attrs = {'name': name}
    options = dict(self.parse_options(m))
    if 'class' in options:
        attrs['class'] = options['class']

    title = self.parse_title(m)
    if not title:
        title = name.capitalize()

    content = self.parse_content(m)
    children = [
        {
            'type': 'admonition_title',
            'text': title,
        },
        {
            'type': 'admonition_content',
            'children': self.parse_tokens(block, content, state),
        }
    ]
    return {
        'type': 'admonition',
        'children': children,
        'attrs': attrs,
    }

def __call__(self, directive: 'BaseDirective', md: 'Markdown') ->None:
    for name in self.SUPPORTED_NAMES:
        directive.register(name, self.parse)

    assert md.renderer is not None
    if md.renderer.NAME == 'html':
        md.renderer.register('admonition', render_admonition)
